package ca.trailbound.app;
import android.content.*;import org.json.*;import java.io.*;import java.net.*;
final class WebUpdater {
 static final int BRIDGE=1;
 static final String SITE="https://saltsenses.github.io/trailbound/";
 final Context context;final File root;final android.content.SharedPreferences prefs;
 volatile String status="Ready to check for updates";private volatile boolean checking;private long lastCheck;
 WebUpdater(Context c){context=c;root=new File(c.getFilesDir(),"web-updates");root.mkdirs();prefs=c.getSharedPreferences("web-updates",Context.MODE_PRIVATE);}
 String activeRevision(){return prefs.getString("active","");}
 File activeDirectory(){String revision=activeRevision();if(!revision.matches("[a-f0-9]{40}"))return null;File f=new File(root,revision);return new File(f,"index.html").isFile()?f:null;}
 private static byte[] readSmall(InputStream in)throws IOException {ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>131072)throw new IOException("Release metadata too large");out.write(buffer,0,n);}return out.toByteArray();}
 String bundledRevision(){try(InputStream in=context.getAssets().open("release.json")){return new JSONObject(new String(readSmall(in),java.nio.charset.StandardCharsets.UTF_8)).getString("revision");}catch(Exception e){return "bundled";}}
 synchronized boolean activateReady(boolean recording){String ready=prefs.getString("ready","");if(ready.isEmpty())return false;if(recording){status="Update downloaded; it will apply after you finish recording.";return false;}File directory=new File(root,ready);if(!new File(directory,"index.html").isFile())return false;String old=activeRevision();if(!prefs.edit().putString("previous",old).putString("active",ready).remove("ready").commit())return false;status="Updated to "+ready.substring(0,7)+". Available offline.";return true;}
 synchronized void rollback(){String failed=activeRevision(),old=prefs.getString("previous","");prefs.edit().putString("rejected",failed).putString("active",old).remove("previous").commit();status="Could not open the new version. Restored the previous offline version.";}
 void check(boolean force,Runnable done){synchronized(this){if(checking||(!force&&System.currentTimeMillis()-lastCheck<60000))return;checking=true;lastCheck=System.currentTimeMillis();}new Thread(()->{try{status="Checking for the latest app and trail data…";byte[] json=download(SITE+"app-update.json?check="+System.currentTimeMillis(),128*1024);JSONObject manifest=new JSONObject(new String(json,java.nio.charset.StandardCharsets.UTF_8));String revision=manifest.getString("revision");String sha=manifest.getString("sha256");long bytes=manifest.getLong("bytes");if(manifest.getInt("format")!=1||!revision.matches("[a-f0-9]{40}")||!sha.matches("[a-f0-9]{64}")||bytes<1||bytes>WebUpdateFiles.MAX_ZIP)throw new IOException("Unsupported update manifest");if(manifest.getInt("minBridge")>BRIDGE){status="A new Android installation is required for this release. Your offline version remains available.";return;}if(revision.equals(prefs.getString("rejected",""))){status="Keeping the previous version after an update failed to start. Waiting for a newer release.";return;}if(revision.equals(activeDirectory()==null?bundledRevision():activeRevision())){status="Up to date · "+revision.substring(0,7)+" · ready offline";return;}if(revision.equals(prefs.getString("ready",""))){status="Latest update downloaded; waiting to apply safely.";return;}status="Downloading the latest app and offline trail data…";byte[] archive=download(SITE+"updates/"+revision+".zip",WebUpdateFiles.MAX_ZIP);if(archive.length!=bytes)throw new IOException("Incomplete update download");stage(archive,revision,sha);status="Update verified and ready.";}catch(Exception e){status="Update check unavailable. Keeping your working offline version; will retry on return.";}finally{checking=false;new android.os.Handler(android.os.Looper.getMainLooper()).post(done);}},"Trailbound-update").start();}
 synchronized void stage(byte[] archive,String revision,String sha)throws Exception {if(!revision.matches("[a-f0-9]{40}"))throw new IOException("Invalid release");File zip=new File(root,"download.zip"),staging=new File(root,"staging"),target=new File(root,revision);try{WebUpdateFiles.remove(staging);try(OutputStream out=new FileOutputStream(zip)){out.write(archive);}WebUpdateFiles.unpack(zip,staging,sha);JSONObject release=new JSONObject(new String(java.nio.file.Files.readAllBytes(new File(staging,"release.json").toPath()),java.nio.charset.StandardCharsets.UTF_8));if(!release.getString("revision").equals(revision)||release.getInt("minBridge")>BRIDGE)throw new IOException("Incompatible release");if(target.exists()&&!revision.equals(activeRevision()))WebUpdateFiles.remove(target);if(!target.exists()&&!staging.renameTo(target))throw new IOException("Cannot stage release");if(!prefs.edit().putString("ready",revision).commit())throw new IOException("Cannot save release state");File[] versions=root.listFiles();if(versions!=null)for(File version:versions)if(version.isDirectory()&&version.getName().matches("[a-f0-9]{40}")&&!version.getName().equals(activeRevision())&&!version.getName().equals(prefs.getString("previous",""))&&!version.getName().equals(revision))WebUpdateFiles.remove(version);}finally{zip.delete();WebUpdateFiles.remove(staging);}}
 private static byte[] download(String url,long max)throws Exception {HttpURLConnection connection=(HttpURLConnection)new URL(url).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(6000);connection.setReadTimeout(20000);connection.setRequestProperty("Cache-Control","no-cache");try{if(connection.getResponseCode()!=200)throw new IOException("Update server unavailable");if(connection.getContentLengthLong()>max)throw new IOException("Update too large");try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[32768];int n;long deadline=System.currentTimeMillis()+120000;while((n=in.read(b))!=-1){if(out.size()+n>max||System.currentTimeMillis()>deadline)throw new IOException("Update limit exceeded");out.write(b,0,n);}return out.toByteArray();}}finally{connection.disconnect();}}
}
